  "anomalies": [
    {
      "category": "missing_component",
      "components": ["FCC2", "NAVC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0100", "NET0152", "NET0089", "NET0170"],
      "observed": "Both MCUs' VCAP pins are assigned signal nets, with no required VCAP-to-GND capacitors shown. FCC2 VCAP pins connect to NET0100 and NET0152; NAVC2 VCAP pins connect to NET0089 and NET0170. NET0100 and NET0152 appear on the UART3_FCC2 connector, and NET0089 appears on the I2C3_NAVC2 connector.",
      "expected": "Each MCU's VCAP pins should have the datasheet-required capacitors to ground and should not be used as external signal nets.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "VCAP 48 NET0100; VCAP 73 NET0152 (FCC sheet, page 2/6)"
        },
        {
          "source": "schematic",
          "quote": "UART3_FCC2: NET0100, NET0152 (FCC Peripherals sheet, page 5/6)"
        },
        {
          "source": "schematic",
          "quote": "VCAP_1 31 NET0089; VCAP_2 47 NET0170 (NAVC sheet, page 3/6)"
        },
        {
          "source": "schematic",
          "quote": "I2C3_NAVC2: NET0039, NET0089 (NAVC Peripherals sheet, page 6/6)"
        }
      ],
      "impact": "The MCUs' internal core regulators may not operate correctly without their required VCAP capacitors, preventing reliable startup or operation. Routing these regulator-output pins to external connectors also risks loading or disturbing the core supply.",
      "confidence": 0.98
    }
  ],
  "summary": "Both MCU symbols show VCAP pins routed onto signal nets rather than to the required local capacitors. At least some of those nets reach external connectors, making this a significant power-integrity and MCU-operation anomaly."
}

